using System.IO;
using System.Text.Json;
using System.Windows;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using VisionFramework;
using VisionPluginContracts;
using VisionPlugins.Calibration;
using W=System.Windows.Controls;

static class Program
{
 static int checks;static readonly List<string> numericDifferences=new();
 static readonly string root=FindRoot();
 static readonly string output=Path.Combine(root,"analysis/full-audit/translation-calibration/checks");
 static string FindRoot(){var p=new DirectoryInfo(AppContext.BaseDirectory);while(p is not null){if(File.Exists(Path.Combine(p.FullName,"VisionReplica.slnx")))return p.FullName;p=p.Parent;}return Environment.CurrentDirectory;}
 static void Check(bool condition,string message){checks++;if(!condition)throw new Exception(message);}
 static Dictionary<string,JsonElement> Defaults(TranslationPlugin p)=>p.Descriptor.Parameters.ToDictionary(x=>x.Name,x=>x.DefaultValue!.Value.Clone());
 [STAThread] static int Main(){try{Directory.CreateDirectory(output);Basic();ReplayFiles();Replay();Console.WriteLine($"TranslationCalibration.PluginChecks: {checks} checks passed");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
 static void Basic(){var plugin=new TranslationPlugin();var values=Defaults(plugin);using var scope=new ModuleExecutionScope();
  int acceptedRows=0;bool importFailed=false;try{TranslationFile.ImportPointText("1 2 3 4 5\r\ninvalid 2 3 4 5\r\n",4,(index,row)=>acceptedRows++);}catch(InvalidDataException){importFailed=true;}Check(importFailed,"Point text rejects bad later row");Check(acceptedRows==1,"Original point import retains written valid prefix");
  Check(values["CalibType"].GetInt32()==0&&values["RotPointTotalNum"].GetInt32()==0,"Translation native defaults");Check(!values.ContainsKey("BasePointX")&&!values.ContainsKey("UseRelativeCoordinates"),"No invented N-point automatic physical parameters");foreach(var p in plugin.Descriptor.Parameters)Check(GraphValidator.ValidParameter(p,values[p.Name]),"Default parameter "+p.Name);
  values["CalibPointTotalNum"]=JsonSerializer.SerializeToElement(4);values["WeightFun"]=JsonSerializer.SerializeToElement(1);
  ModuleResult Run(string id,Dictionary<string,PortValue>? input=null)=>plugin.CreateRuntime().ExecuteAsync(new(id,root,input??new(),values){Scope=scope},CancellationToken.None).AsTask().GetAwaiter().GetResult();
  Check(Run("node").NativeErrorCode==0xe000031c,"Missing image input propagates original no-data error");
  var empty=Run("node",new(){{"ImagePointX",PortValue.Numbers([])},{"ImagePointY",PortValue.Numbers([])}});Check(empty.Status==ModuleStatus.Success&&empty.Outputs["CalibCurIndex"].As<long>()==0,"Bound empty is successful incomplete");Check(empty.Outputs.ContainsKey("WorldRotateAngle")&&!empty.Outputs.ContainsKey("Rotate")&&!empty.Outputs.ContainsKey("IsRightCoorA"),"Incomplete native output presence");
  var part=Run("node",new(){{"ImagePointX",PortValue.Numbers([0,10])},{"ImagePointY",PortValue.Numbers([0,0])}});Check(part.Outputs["WorldPointX"].As<IReadOnlyList<double>>().SequenceEqual(new[]{0d,0}),"Missing physical coordinates preserve zero values without automatic grid");
  Check(Run("other").NativeErrorCode==0xe000031c,"Per-node state isolation");
  values["ClearRevision"]=JsonSerializer.SerializeToElement(1);Run("node");var input=new Dictionary<string,PortValue>{{"ImagePointX",PortValue.Numbers([0,10,0,10])},{"ImagePointY",PortValue.Numbers([0,0,10,10])},{"PhysicalPointX",PortValue.Numbers([10,30,10,30])},{"PhysicalPointY",PortValue.Numbers([-5,-5,15,15])}};var complete=Run("node",input);Check(complete.Status==ModuleStatus.Success,"Complete physical point calibration");Check(complete.Outputs.ContainsKey("IsRightCoorA")&&!complete.Outputs.ContainsKey("CalibErrStatus"),"Completed Translation uses IsRightCoorA");Check(complete.Outputs["IsRightCoorA"].As<long>()==1,"Positive matrix orientation");var mapped=complete.Outputs["CalibData"].As<CalibrationData>().Transform(3,4);Check(Math.Abs(mapped.X-16)<.001&&Math.Abs(mapped.Y-3)<.001,"Actual calibration mapping");
  var context=new ToolEditorContext(new("node",TranslationPlugin.Id,"1.0.0","平移旋转标定",values),root,_=>{},_=>Task.FromException<NodeRunRecord>(new Exception())){Scope=scope};plugin.Export(context,Path.Combine(output,"independent.xml"));Check(System.Xml.Linq.XDocument.Load(Path.Combine(output,"independent.xml")).Descendants("CalibFloatListParam").Single().Elements("ParamValue").Count()==9,"Module XML matrix output");
  var persisted=plugin.PrepareSave(context.Node,root,new ResourceCatalog(root,[]),scope);Check(persisted.Node.Parameters["ImagePointX1"].GetDouble()==10,"Captured table persists");
  if(System.Windows.Application.Current is null)new System.Windows.Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};var uiValues=Defaults(plugin);var uiContext=context with{Node=context.Node with{Id="ui",Parameters=uiValues},Apply=v=>uiValues=v};var window=new TranslationWindow(uiContext,plugin){Left=-30000,Top=-30000,ShowActivated=false,ShowInTaskbar=false};window.Show();window.UpdateLayout();Check(Find<W.ComboBox>(window,"CalibType")?.SelectedIndex==0,"Default translation UI");Check(Find<System.Windows.Controls.Primitives.ToggleButton>(window,"UnionCalibEnable") is null,"Translation mode hides union");Capture(window,"independent-translation.png");Find<W.ComboBox>(window,"CalibType")!.SelectedIndex=1;window.UpdateLayout();Check(Find<System.Windows.Controls.Primitives.ToggleButton>(window,"UnionCalibEnable") is not null,"Rotation mode shows union");Check(Find<W.ComboBox>(window,"CameraMode")!.Items.Count==2,"Original two camera choices");Capture(window,"independent-translation-rotation.png");Find<W.RadioButton>(window,"CalibPointInput1")!.IsChecked=true;window.UpdateLayout();Check(Find<W.TextBox>(window,"InputImagePointX") is not null,"XY input mode");Find<W.ComboBox>(window,"CalibPointGet")!.SelectedIndex=1;window.UpdateLayout();Check(Find<System.Windows.Controls.Primitives.ToggleButton>(window,"TeachEnable") is null&&Find<W.TextBox>(window,"InputImagePointX") is null,"Manual hides input and teach");Capture(window,"independent-manual.png");window.Close();
 }
 static void Replay(){string path=Path.Combine(root,"docs/plugins/translation-calibration-evidence.json");if(!File.Exists(path))throw new FileNotFoundException("Generate Translation evidence before checks",path);using var evidence=JsonDocument.Parse(File.ReadAllText(path));var plugin=new TranslationPlugin();var values=Defaults(plugin);using var scope=new ModuleExecutionScope();string id="";int scenarios=0;
  ToolEditorContext Context()=>new(new(id,TranslationPlugin.Id,"1.0.0",id,values),root,_=>{},_=>Task.FromException<NodeRunRecord>(new Exception())){Scope=scope};
  foreach(var row in evidence.RootElement.GetProperty("events").EnumerateArray()){string phase=row.GetProperty("phase").GetString()!;if(phase=="instance-start"){id="replay-"+row.GetProperty("serial").GetInt32();values=Defaults(plugin);continue;}if(phase=="set"){string key=row.GetProperty("key").GetString()!,text=row.GetProperty("value").GetString()!;if(key=="Clear"){values["ClearRevision"]=JsonSerializer.SerializeToElement(values["ClearRevision"].GetInt32()+1);plugin.UpdateConfiguration(Context(),values);plugin.Clear(Context());continue;}var spec=plugin.Descriptor.Parameters.FirstOrDefault(p=>p.Name==key);if(spec is not null){values[key]=spec.Kind switch{ParameterKind.Integer=>JsonSerializer.SerializeToElement(int.Parse(text,System.Globalization.CultureInfo.InvariantCulture)),ParameterKind.Number=>JsonSerializer.SerializeToElement(double.Parse(text,System.Globalization.CultureInfo.InvariantCulture)),ParameterKind.Boolean=>JsonSerializer.SerializeToElement(bool.Parse(text)),_=>JsonSerializer.SerializeToElement(text)};plugin.UpdateConfiguration(Context(),values);}continue;}
   if(!row.TryGetProperty("rawMembers",out var raw))continue;if(phase.StartsWith("after-clear")||phase=="clear-raw-angle-retention"){if(phase=="after-clear-no-input"){}else{var state=plugin.Snapshot(Context());for(int i=0;i<32;i++)Check(state[i,5]==raw.GetProperty("angles16430")[i].GetSingle(),phase+" preserved image angle "+i);continue;}}
   scenarios++;var inputs=row.GetProperty("inputs").EnumerateObject().ToDictionary(p=>p.Name,p=>PortValue.Numbers(p.Value.EnumerateArray().Select(v=>v.GetDouble())));foreach(var pair in row.GetProperty("strings").EnumerateObject())inputs[pair.Name]=PortValue.Text(pair.Value.GetString()!);var result=plugin.CreateRuntime().ExecuteAsync(new(id,root,inputs,values){Scope=scope},CancellationToken.None).AsTask().GetAwaiter().GetResult();var snapshot=plugin.Snapshot(Context());if(phase=="camera1-union-rotation")DebugUnion(snapshot,values,result);for(int i=0;i<32;i++){Check(snapshot[i,4]==raw.GetProperty("angles163b0")[i].GetSingle(),phase+" physical angle "+i);Check(snapshot[i,5]==raw.GetProperty("angles16430")[i].GetSingle(),phase+" image angle "+i);}if(phase=="synthetic-output-failure")continue;
   Check(result.NativeErrorCode==row.GetProperty("code").GetUInt32(),phase+" original return code");var published=row.GetProperty("writes").EnumerateArray().Where(w=>w.GetProperty("returned").GetUInt32()==0).ToDictionary(w=>w.GetProperty("name").GetString()!);Check(result.Outputs.Keys.Except(new[]{"ModuRunTime","CalibData"}).ToHashSet().SetEquals(published.Keys),phase+" exact output presence");foreach(var pair in published){var expected=pair.Value.GetProperty("values").EnumerateArray().Select(x=>x.GetDouble()).ToArray();var actual=result.Outputs[pair.Key];if(actual.Kind==DataKind.NumberArray)Check(actual.As<IReadOnlyList<double>>().SequenceEqual(expected.Select(x=>(double)(float)x)),phase+" array "+pair.Key);else if(actual.Kind==DataKind.Integer){checks++;if(actual.As<long>()!=expected[0])numericDifferences.Add(phase+" integer "+pair.Key+" actual="+actual.As<long>()+" original="+expected[0]);}else if(expected.All(double.IsFinite)){checks++;if(Math.Abs(actual.As<double>()-expected[0])>Math.Max(.001,Math.Abs(expected[0])*.000001))numericDifferences.Add(phase+" float "+pair.Key+" actual="+actual.As<double>()+" original="+expected[0]);}}
  }Check(scenarios>=30,"Broad original Process scenarios replayed");File.WriteAllLines(Path.Combine(output,"numeric-differences.txt"),numericDifferences);Check(numericDifferences.Count==0,"Original numeric differences: "+string.Join("; ",numericDifferences.Take(8)));
 }
 static void ReplayFiles(){using var evidence=JsonDocument.Parse(File.ReadAllText(Path.Combine(root,"docs/plugins/translation-calibration-evidence.json")));var values=Defaults(new TranslationPlugin());int count=0,fileOrigin=0;foreach(var row in evidence.RootElement.GetProperty("events").EnumerateArray()){string phase=row.GetProperty("phase").GetString()!;if(phase=="instance-start"){values=Defaults(new TranslationPlugin());fileOrigin=0;continue;}if(phase=="set"){string key=row.GetProperty("key").GetString()!,text=row.GetProperty("value").GetString()!;if(values.TryGetValue(key,out var old))values[key]=old.ValueKind switch{JsonValueKind.Number=>new TranslationPlugin().Descriptor.Parameters.Single(p=>p.Name==key).Kind==ParameterKind.Integer?JsonSerializer.SerializeToElement(int.Parse(text,System.Globalization.CultureInfo.InvariantCulture)):JsonSerializer.SerializeToElement(double.Parse(text,System.Globalization.CultureInfo.InvariantCulture)),JsonValueKind.True or JsonValueKind.False=>JsonSerializer.SerializeToElement(bool.Parse(text)),_=>JsonSerializer.SerializeToElement(text)};continue;}if(phase!="file"||row.GetProperty("code").GetUInt32()!=0)continue;string name=row.GetProperty("name").GetString()!;var original=evidence.RootElement.GetProperty("files").EnumerateArray().Single(f=>f.GetProperty("name").GetString()==name);var expected=System.Xml.Linq.XDocument.Parse(original.GetProperty("xml").GetString()!);var input=expected.Root!.Element("CalibInputParam")!.Elements().ToDictionary(e=>e.Attribute("ParamName")!.Value);var native=expected.Root.Element("CalibOutputParam")!.Elements().ToDictionary(e=>e.Attribute("ParamName")!.Value);double Number(string key)=>double.Parse(input[key].Element("ParamValue")!.Value,System.Globalization.CultureInfo.InvariantCulture);double Field(string group,string key)=>double.Parse(native[group].Element(key)!.Value,System.Globalization.CultureInfo.InvariantCulture);int trans=(int)Number("TransNum"),rot=(int)Number("RotNum");values["CalibPointTotalNum"]=JsonSerializer.SerializeToElement(trans);values["RotPointTotalNum"]=JsonSerializer.SerializeToElement(rot);var points=new float[32,6];var images=input["ImagePointLst"].Elements("PointF").ToArray();var worlds=input["WorldPointLst"].Elements("PointF").ToArray();for(int i=0;i<images.Length;i++)for(int axis=0;axis<3;axis++){string key=new[]{"X","Y","R"}[axis];points[i,axis==2?5:axis]=float.Parse(images[i].Element(key)!.Value,System.Globalization.CultureInfo.InvariantCulture);points[i,axis==2?4:axis+2]=float.Parse(worlds[i].Element(key)!.Value,System.Globalization.CultureInfo.InvariantCulture);}var result=new NPointSolveResult{Status=(int)Number("CalibErrStatus"),Matrix=native["CalibMatrix"].Elements("ParamValue").Select(v=>double.Parse(v.Value,System.Globalization.CultureInfo.InvariantCulture)).ToArray(),OffsetError=Number("TransError"),RotateError=Number("RotError"),OffsetWorldError=Number("TransWorldError"),RotateWorldError=Number("RotWorldError"),PixelPrecision=Number("PixelPrecision"),Direction=(int)double.Parse(native["RotDirectionState"].Element("ParamValue")!.Value,System.Globalization.CultureInfo.InvariantCulture),CenterImageX=Field("RotCenterImagePoint","RotCenterImagePointX"),CenterImageY=Field("RotCenterImagePoint","RotCenterImagePointY"),CenterWorldX=Field("RotCenterWorldPoint","RotCenterWorldPointX"),CenterWorldY=Field("RotCenterWorldPoint","RotCenterWorldPointY")};bool hasTeach=native.ContainsKey("SnapImage");var teach=hasTeach?new[]{(float)Field("SnapImage","SnapImagePointX"),(float)Field("SnapImage","SnapImagePointY"),(float)Field("SnapImage","SnapImageR"),(float)Field("TeachWorld","TeachWorldPointX"),(float)Field("TeachWorld","TeachWorldPointY"),(float)Field("TeachWorld","TeachWorldR")}:new float[6];string path=Path.Combine(output,name+"-file.xml");TranslationFile.Write(path,points,trans+rot,values,result,hasTeach,teach,fileOrigin);if(hasTeach)fileOrigin=(trans-1)/2;var actual=System.Xml.Linq.XDocument.Load(path);foreach(string section in new[]{"CalibInputParam","CalibOutputParam"}){var a=actual.Root!.Element(section)!.Elements().ToDictionary(e=>e.Attribute("ParamName")!.Value);var b=expected.Root.Element(section)!.Elements().ToDictionary(e=>e.Attribute("ParamName")!.Value);Check(a.Keys.ToHashSet().SetEquals(b.Keys),name+" XML keys "+section);foreach(var pair in b){if(pair.Key=="CreateCalibTime")continue;var actualLeaves=a[pair.Key].Descendants().Where(e=>!e.HasElements).Select(e=>e.Value).ToArray();var sourceLeaves=pair.Value.Descendants().Where(e=>!e.HasElements).Select(e=>e.Value).ToArray();Check(actualLeaves.Length==sourceLeaves.Length,name+" XML leaf count "+pair.Key);for(int i=0;i<sourceLeaves.Length;i++){if(double.TryParse(sourceLeaves[i],System.Globalization.NumberStyles.Float,System.Globalization.CultureInfo.InvariantCulture,out double v))Check(Math.Abs(double.Parse(actualLeaves[i],System.Globalization.CultureInfo.InvariantCulture)-v)<=Math.Max(1e-6,Math.Abs(v)*3e-6),name+" XML numeric "+pair.Key);else Check(actualLeaves[i]==sourceLeaves[i],name+" XML text "+pair.Key);}}}count++;}Check(count>=15,"Original Translation module file fixtures");}
 static void DebugUnion(float[,] p,Dictionary<string,JsonElement> values,ModuleResult result){int trans=values["CalibPointTotalNum"].GetInt32(),rot=values["RotPointTotalNum"].GetInt32();var offsets=Enumerable.Range(0,trans).Select(i=>new NPointPair(p[i,0],p[i,1],p[i,2],p[i,3])).ToArray();var h=NPointSolver.Solve(offsets,[],new(2,3,1)).Matrix;var inv=(double[])typeof(TranslationSolve).GetMethod("Inverse",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Static)!.Invoke(null,new object[]{h})!;int anchor=trans+(rot-1)/2;var points=Enumerable.Range(trans,rot).Select(i=>{float x=(float)(p[i,0]+(float)((p[anchor,2]-p[i,2])*(float)inv[0])+(float)((p[anchor,3]-p[i,3])*(float)inv[1]));float y=(float)(p[i,1]+(float)((p[anchor,2]-p[i,2])*(float)inv[3])+(float)((p[anchor,3]-p[i,3])*(float)inv[4]));return new{x,y,xBits=BitConverter.SingleToInt32Bits(x),yBits=BitConverter.SingleToInt32Bits(y),mappedX=(float)(h[0]*x+h[1]*y+h[2]),mappedY=(float)(h[3]*x+h[4]*y+h[5])};}).ToArray();var fields=result.Outputs.Where(x=>x.Key.StartsWith("Rot")).ToDictionary(x=>x.Key,x=>x.Value.Value);File.WriteAllText(Path.Combine(output,"union-debug.json"),JsonSerializer.Serialize(new{h,inv,points,fields},new JsonSerializerOptions{WriteIndented=true}));}
 static T? Find<T>(DependencyObject p,string name)where T:FrameworkElement{if(p is T t&&t.Name==name)return t;for(int i=0;i<VisualTreeHelper.GetChildrenCount(p);i++)if(Find<T>(VisualTreeHelper.GetChild(p,i),name)is{} c)return c;return null;}
 static void Capture(Window window,string name){window.UpdateLayout();var bitmap=new RenderTargetBitmap((int)window.ActualWidth,(int)window.ActualHeight,96,96,PixelFormats.Pbgra32);bitmap.Render(window);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bitmap));using var file=File.Create(Path.Combine(output,name));encoder.Save(file);}
}
